pub enum GltfReorderScenesInverseOperation { Insert { position: usize, item: GltfScene }, Delete { index: usize, removed: GltfScene }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfReorderScenesInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfReorderScenesPayload, pub operation: GltfReorderScenesInverseOperation }
