fn operation(payload: &GltfReorderScenesPayload, base: &GltfSnapshot) -> GltfReorderScenesInverseOperation { GltfReorderScenesInverseOperation::Reorder { order: (0..payload.order.len()).map(|index| payload.order.iter().position(|value| *value == index).unwrap()).collect() } }
