pub fn apply_inverse(inverse: &GltfReorderScenesInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfReorderScenesInverseOperation::Insert { position, .. } if *position > after.document.scenes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/scenes", "position must be within the collection")), GltfReorderScenesInverseOperation::Delete { index, .. } if *index >= after.document.scenes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/scenes", "index must address an item")), GltfReorderScenesInverseOperation::Move { index, position } if *index >= after.document.scenes.len() || *position >= after.document.scenes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/scenes", "indices must address items")), GltfReorderScenesInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.scenes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.scenes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/scenes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfReorderScenesInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Scenes, &Change::Insert(*position))?; next.document.scenes.insert(*position, item.clone());  }, GltfReorderScenesInverseOperation::Delete { index, .. } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, None, None)?;  }, GltfReorderScenesInverseOperation::Move { index, position } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, *index, Some(*position), None)?;  }, GltfReorderScenesInverseOperation::Reorder { order } => { scenes_op(&mut next, GltfTopLevelFamily::Scenes, order[0], None, Some(order))?;  } } Ok(next) }
